package com.dandimate.durooduroo.scroll.domain;
import jakarta.persistence.*; import java.time.LocalDateTime; import java.util.UUID;
@Entity @Table(name="paragraph_reactions", uniqueConstraints=@UniqueConstraint(name="uk_paragraph_reactions_member", columnNames={"paragraph_id","member_id"})) public class ParagraphReaction { @Id private String id; @Column(name="paragraph_id",nullable=false) private String paragraphId; @Column(name="member_id",nullable=false) private String memberId; @Column(nullable=false) private LocalDateTime createdAt; protected ParagraphReaction(){} private ParagraphReaction(String p,String m){id=UUID.randomUUID().toString();paragraphId=p;memberId=m;createdAt=LocalDateTime.now();} public static ParagraphReaction ahMatda(String paragraphId,String memberId){return new ParagraphReaction(paragraphId,memberId);} public String getId(){return id;} public String getParagraphId(){return paragraphId;} public String getMemberId(){return memberId;} }
